<?php
require_once __DIR__.'/includes/config.php'; require_login(); require_permission('reports');
$uid=(int)$_SESSION['user_id']; $from=$_GET['from']??date('Y-m-01'); $to=$_GET['to']??date('Y-m-d');
$vf=DateTime::createFromFormat('!Y-m-d',$from); $vt=DateTime::createFromFormat('!Y-m-d',$to); if(!$vf||$vf->format('Y-m-d')!==$from)$from=date('Y-m-01'); if(!$vt||$vt->format('Y-m-d')!==$to)$to=date('Y-m-d'); if($from>$to){[$from,$to]=[$to,$from];} $end=date('Y-m-d 00:00:00',strtotime($to.' +1 day')); $start=$from.' 00:00:00';
$export=$_GET['export']??'';
if($export==='sales'){$q=$pdo->prepare('SELECT s.id,s.created_at,c.name customer,s.payment_method,s.total,s.amount_paid,(s.total-s.amount_paid) balance,COALESCE((SELECT SUM((si.unit_price-si.unit_cost)*si.quantity) FROM sale_items si WHERE si.sale_id=s.id),0) gross_profit FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.user_id=? AND s.created_at>=? AND s.created_at<? ORDER BY s.created_at DESC');$q->execute([$uid,$start,$end]);$rows=$q->fetchAll();csv_out('kasuwalink-sales-'.$from.'-to-'.$to.'.csv',['Sale ID','Date','Customer','Payment method','Total NGN','Paid NGN','Balance NGN','Gross profit NGN'],array_map(fn($r)=>[$r['id'],$r['created_at'],$r['customer']??'Walk-in',$r['payment_method'],$r['total'],$r['amount_paid'],$r['balance'],$r['gross_profit']],$rows));}
if($export==='expenses'){$q=$pdo->prepare('SELECT expense_date,title,amount FROM expenses WHERE user_id=? AND expense_date BETWEEN ? AND ? ORDER BY expense_date DESC');$q->execute([$uid,$from,$to]);csv_out('kasuwalink-expenses-'.$from.'-to-'.$to.'.csv',['Date','Description','Amount NGN'],$q->fetchAll(PDO::FETCH_NUM));}
if($export==='inventory'){$q=$pdo->prepare('SELECT name,sku,quantity,low_stock_threshold,cost_price,selling_price,(quantity*cost_price) stock_cost_value,(quantity*selling_price) potential_retail_value FROM products WHERE user_id=? ORDER BY name');$q->execute([$uid]);csv_out('kasuwalink-inventory-'.date('Y-m-d').'.csv',['Product','SKU','Quantity','Low-stock threshold','Unit cost NGN','Selling price NGN','Stock cost value NGN','Potential retail value NGN'],$q->fetchAll(PDO::FETCH_NUM));}
if($export==='monthly'){$q=$pdo->prepare("SELECT DATE_FORMAT(s.created_at,'%Y-%m') month,COUNT(*) transactions,COALESCE(SUM(s.total),0) sales_value,COALESCE(SUM(s.amount_paid),0) collected,COALESCE(SUM(s.total-s.amount_paid),0) outstanding,COALESCE((SELECT SUM((si.unit_price-si.unit_cost)*si.quantity) FROM sale_items si JOIN sales sx ON sx.id=si.sale_id WHERE sx.user_id=s.user_id AND DATE_FORMAT(sx.created_at,'%Y-%m')=DATE_FORMAT(s.created_at,'%Y-%m')),0) gross_profit FROM sales s WHERE s.user_id=? AND s.created_at>=? AND s.created_at<? GROUP BY DATE_FORMAT(s.created_at,'%Y-%m') ORDER BY month");$q->execute([$uid,$start,$end]);csv_out('kasuwalink-monthly-summary-'.$from.'-to-'.$to.'.csv',['Month','Transactions','Sales value NGN','Collected NGN','Outstanding NGN','Gross profit NGN'],$q->fetchAll(PDO::FETCH_NUM));}
function csv_out(string $filename,array $headers,array $rows): never { header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="'.$filename.'"'); $out=fopen('php://output','w'); fwrite($out,"\xEF\xBB\xBF"); fputcsv($out,$headers); foreach($rows as $r)fputcsv($out,$r); fclose($out); exit; }
$q=$pdo->prepare('SELECT COUNT(*) count,COALESCE(SUM(total),0) total,COALESCE(SUM(amount_paid),0) paid FROM sales WHERE user_id=? AND created_at>=? AND created_at<?');$q->execute([$uid,$start,$end]);$sales=$q->fetch();$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE user_id=? AND expense_date BETWEEN ? AND ?');$q->execute([$uid,$from,$to]);$expenseTotal=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM((si.unit_price-si.unit_cost)*si.quantity),0) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.user_id=? AND s.created_at>=? AND s.created_at<?');$q->execute([$uid,$start,$end]);$grossProfit=(float)$q->fetchColumn();$netEstimate=$grossProfit-$expenseTotal;
$q=$pdo->prepare("SELECT DATE_FORMAT(s.created_at,'%Y-%m') month,COUNT(*) transactions,COALESCE(SUM(s.total),0) sales_value,COALESCE(SUM(s.amount_paid),0) collected,COALESCE(SUM(s.total-s.amount_paid),0) outstanding FROM sales s WHERE s.user_id=? AND s.created_at>=? AND s.created_at<? GROUP BY DATE_FORMAT(s.created_at,'%Y-%m') ORDER BY month DESC LIMIT 12");$q->execute([$uid,$start,$end]);$months=$q->fetchAll();
$pageTitle='Reports'; require __DIR__.'/includes/header.php'; ?>
<div class="page-heading"><div><h1 class="h3 fw-bold mb-1">Reports & exports</h1><p class="muted mb-0">Track sales, collected cash, gross profit and operating expenses.</p></div></div>
<div class="card mb-4"><div class="card-body"><form method="get" class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>" required></div><div class="col-md-4"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>" required></div><div class="col-md-4"><button class="btn btn-primary">Apply dates</button></div></form></div></div>
<div class="row g-3 mb-4"><div class="col-md-4"><div class="card stat-card"><div class="stat-label">Transactions</div><div class="stat-value"><?=(int)$sales['count']?></div></div></div><div class="col-md-4"><div class="card stat-card"><div class="stat-label">Sales value</div><div class="stat-value"><?=money($sales['total'])?></div><div class="small text-secondary">Collected: <?=money($sales['paid'])?></div></div></div><div class="col-md-4"><div class="card stat-card"><div class="stat-label">Outstanding sales balance</div><div class="stat-value"><?=money((float)$sales['total']-(float)$sales['paid'])?></div></div></div><div class="col-md-4"><div class="card stat-card"><div class="stat-label">Gross profit*</div><div class="stat-value"><?=money($grossProfit)?></div></div></div><div class="col-md-4"><div class="card stat-card"><div class="stat-label">Recorded expenses</div><div class="stat-value"><?=money($expenseTotal)?></div></div></div><div class="col-md-4"><div class="card stat-card"><div class="stat-label">Estimated net result*</div><div class="stat-value"><?=money($netEstimate)?></div></div></div></div>
<div class="card mb-4"><div class="card-body p-4"><h2 class="h5 fw-bold">Download records</h2><p class="muted">CSV files open in Microsoft Excel and Google Sheets.</p><div class="d-flex gap-2 flex-wrap"><?php foreach(['sales'=>'Sales history','expenses'=>'Expenses','inventory'=>'Current inventory','monthly'=>'Monthly summary'] as $key=>$label):?><a class="btn btn-outline-primary" href="?from=<?=e($from)?>&amp;to=<?=e($to)?>&amp;export=<?=$key?>">Export <?=$label?></a><?php endforeach;?></div><p class="small text-secondary mt-3 mb-0">*Gross profit is calculated from saved sale-item costs. Estimated net result is gross profit minus expenses recorded in this period; it is not a formal accounting statement and may exclude taxes, fees, unsold-stock adjustments and unrecorded costs.</p></div></div>
<div class="card"><div class="card-body"><h2 class="h5 fw-bold mb-3">Monthly sales breakdown</h2><div class="table-responsive"><table class="table"><thead><tr><th>Month</th><th>Transactions</th><th>Sales value</th><th>Collected</th><th>Outstanding</th></tr></thead><tbody><?php foreach($months as $m):?><tr><td><?=e($m['month'])?></td><td><?=(int)$m['transactions']?></td><td><?=money($m['sales_value'])?></td><td><?=money($m['collected'])?></td><td><?=money($m['outstanding'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$months):?><div class="empty-state">No sales were found for this date range.</div><?php endif;?></div></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
